@ConfigurationProperties
public record CatalogoRechazos(Map<String, Fila> rechazos) {
    public record Fila(String texto, int externo) {}
    public CodigoRechazo get(int interno) {
        var f = rechazos.get("%04d".formatted(interno));
        return f == null ? new CodigoRechazo(interno, "", 0) : new CodigoRechazo(interno, f.texto(), f.externo());
    }
}

@Configuration
@RequiredArgsConstructor
public class GatewayFlowConfig {

    private final InicioGateway inicio;          // 00000000-FORMA-ETIQ-TASKFILE + 10000000 + 20000000-VALIDA-INICIO
    private final ManejadorTransaccion manejador; // 50300000-MANEJA-TRANSACCION

    /** MAIN-PGM: PERFORM 50000000-PROCESO-PGM UNTIL WS-EOJ. */
    @Bean
    IntegrationFlow lincoms(ConnectionFactory mq) {
        return IntegrationFlow
                .from(Jms.messageDrivenChannelAdapter(mq).destination("s500.lincoms.in"))  // COMS input
                .filter(Message.class, m -> !inicio.esFinDeTrabajo(m))                        // WS-EOJ y fin de prelínea
                .handle(manejador, "maneja")
                .channel("s500.lincoms.out")                                                // 50390000-ENVIA-MSG
                .get();
    }

    @EventListener(ApplicationReadyEvent.class)
    void arranque() { inicio.validaInicio(); }      // 20000000-VALIDA-INICIO

    @PreDestroy
    void fin() { inicio.finPrograma(); }            // 70000000-FIN-PGM
}

/** INTERRUPT-BY-HI: cada TASKVALUE se vuelve una operación del endpoint, sin detener el servicio. */
@Component
@Endpoint(id = "lincoms")
@RequiredArgsConstructor
public class OperacionGatewayEndpoint {

    private final BanderasGateway banderas;   // estado compartido, antes en WORKING-STORAGE

    /** HI 1010: alterna la validación con S041 (MOVE 0/1 TO WS-S041-SEGURIDAD-VA). */
    @WriteOperation
    public Map<String, Object> seguridad() {
        boolean ahora = banderas.alternaSeguridadS041();
        if (!ahora) seguridadS041.liberar();     // CANCEL "SEGURIDAD"
        return Map.of("s041", ahora);            // displays 018 / 019
    }

    /** HI 1011: alterna la validación Teletón (VALUE 0 = encendida). */
    @WriteOperation
    public Map<String, Object> teleton() {
        return Map.of("teleton", banderas.alternaTeleton());   // displays 059 / 060
    }

    private final SeguridadS041Client seguridadS041;
}

@Service
@RequiredArgsConstructor
public class AperturaBases {

    private final DataSource captacion;   // ORIGINAL = S500BD01CAPTACION
    private final DataSource auxiliar;    // S500BD02AUXILIAR

    /** 40300000-ABRE-DB: el modo fija qué base es de solo lectura. */
    public Conexiones abre(ModoProceso modo) {
        return switch (modo) {
            case LINEA    -> new Conexiones(rw(captacion), null);
            case PREBATCH -> new Conexiones(ro(captacion), rw(auxiliar));
            case PRELINEA -> new Conexiones(rw(captacion), rw(auxiliar));
        };
        // ON EXCEPTION CALL SYSTEM DMTERMINATE: una SQLException al abrir detiene el arranque.
    }

    private static Connection ro(DataSource ds) throws SQLException {
        Connection c = ds.getConnection(); c.setReadOnly(true); return c;   // OPEN INQUIRY
    }
    private static Connection rw(DataSource ds) throws SQLException {
        return ds.getConnection();                                          // OPEN UPDATE
    }
}

@Component
@RequiredArgsConstructor
public class TransaccionRouter {

    private final ValidaRecepcion valida;           // 51080500-VALIDA-RECIBE-MOVTOS
    private final Abonos abonos; private final Cargos cargos;
    private final Eliminaciones eliminaciones; private final NoContables noContables;
    private final CuentaMovil cuentaMovil;
    private final GatewayProperties props;

    /** 51000000-PROCESA-TRANSACCION. */
    public void procesa(Transaccion tx) {
        if (tx.compensacionObanco()) return;          // WS-88-COMPENSACION-OBANC: NEXT SENTENCE
        valida.recepcion(tx);
        if (tx.contrato().pimPerfilesDolares()) perfilesDolares.aplica(tx);
        if (!tx.contrato().productoSoriana()) observacion.checa(tx);   // 00000000-CHECA-CTA-ENOBS
        if (tx.conError()) return;

        if (tx.cuentaMovil()) {
            if (tx.tipoMov() == TipoMov.ABONO || tx.tipoMov() == TipoMov.CARGO) cuentaMovil.cargoAbono(tx);
            else cuentaMovil.eliminacion(tx);
            return;
        }
        switch (tx.tipoMov()) {                         // WS17-88-TIPMOV-*
            case ABONO   -> abonos.procesa(tx);
            case ELIM    -> eliminaciones.procesa(tx);
            case CARGO   -> cargos.procesa(tx);
            case NOCONT  -> { if (tx.clave() != props.claveNoContableExcluida()) noContables.procesa(tx); }  // 0544
        }
    }
    private final PerfilesDolares perfilesDolares; private final CuentaEnObservacion observacion;
}

@Service
@RequiredArgsConstructor
public class SeguridadS041Service {

    private final SeguridadS041Client s041;   // CALL a la librería SEGURIDAD

    /** Tabla 50310990-VALIDA-STATUS-S041: resultado negativo a código interno. */
    private static final Map<Integer, Integer> RECHAZO = Map.of(
            -2, 154, -3, 160, -4, 477, -5, 156, -6, 157,
            -7, 155, -8, 158, -9, 166, -10, 159, -11, 161);
    private static final int RECHAZO_DESCONOCIDO = 167;

    public void valida(Transaccion tx) {
        var r = s041.valida(tx.claveSeguridad(), tx.monedaSeguridad(), tx.importe());
        if (r.resultado() == 0 || r.resultado() == 1) {
            tx.nominas(nomina(r.nominaOpe()), nomina(r.nominaFun1()), nomina(r.nominaFun2()));
            tx.indicadorFirma(r.resultado() == 0 ? 2 : 1);     // WS-GEN-INDFIRMA
            return;
        }
        tx.rechaza(RECHAZO.getOrDefault(r.resultado(), RECHAZO_DESCONOCIDO));
    }

    /** COMPUTE ... ON SIZE ERROR MOVE 0: una nómina que no cabe se registra como cero. */
    private static long nomina(long v) {
        return (v < 0 || v > NominaPic.MAX) ? 0L : v;
    }
}

/** WS-S500-QUIEN-VA: quién atiende la transacción. Los valores son los del fuente. */
public enum QuienVa { LOCAL_APLI(2), FORANEO_APLI(1), NOCONT_APLI(17), LOCAL_TERM(4),
                      FORANEO_TERM(5), NOCONT_FOR_TERM(18), NO_BNMX(14); /* ... */ }

@Component
public class RuteoCsi {

    /** 50311300-AQUE-CSIPERTENECE, después de validar sucursales (errores 0003 y 0005). */
    public Optional<QuienVa> decide(Transaccion tx, int csiControl) {
        if (tx.bancoNoBanamex()) return Optional.of(QuienVa.NO_BNMX);
        boolean local = tx.csiContrato() == csiControl;      // WS-CSI-CTO = WS02-NUM-CSI
        boolean contable = tx.esCargoAbonoOEliminacion() && !tx.ctaMaestraDolaresMn();

        if (tx.vinoDeAplicacion()) {
            if (local) { tx.marcaProcesaLocal(); return Optional.of(QuienVa.LOCAL_APLI); }
            if (tx.procesoAdisp() || tx.esClaveIndicadorNivel()) return rechazo(tx);
            if (contable || tx.chequeSalvoBuenCobro()) return Optional.of(QuienVa.FORANEO_APLI);
            if (tx.ica() && tx.sistemaOrigen() == 16 && tx.noContable()) return rechazo(tx);
            return tx.noContable() ? Optional.of(QuienVa.NOCONT_APLI) : rechazo(tx);
        }
        if (local) {
            if (tx.soloValidaCsi()) return Optional.empty();   // NEXT SENTENCE: no marca proceso
            tx.marcaProcesaLocal(); return Optional.of(QuienVa.LOCAL_TERM);
        }
        if (contable) return Optional.of(QuienVa.FORANEO_TERM);
        return tx.noContableForaneoTerminal() ? Optional.of(QuienVa.NOCONT_FOR_TERM) : rechazo(tx);
    }

    private static Optional<QuienVa> rechazo(Transaccion tx) {
        tx.rechaza(250);   // TRANSACCION NO PERMITIDA PARA DIALOGO FORANEO
        return Optional.empty();
    }
}

@Component
@RequiredArgsConstructor
public class RespuestaFraudManagerHandler {

    private final RespuestaFraudManagerService respuesta;   // 50312200-RESPUESTA-FRAUD-MGR
    private final TimeoutsFraudManager timeouts;             // 00000000-BORRINC-ASFM-TIMEOUTS
    private final GatewayProperties props;                   // tcorigen de FM y de revocación

    /** 50312205-CTRL-RESP-FRAUD-MGR. */
    @ServiceActivator(inputChannel = "fm.respuestas")
    public void maneja(DialogoFm d, Transaccion tx) {
        if (d.tcOrigen() == props.tcOrigenRevocaFm()) {
            tx.folioFm(d.autorizacion());                     // respuesta de timeout
        } else if (d.tcOrigen() == props.tcOrigenFraudManager()) {
            switch (d.indAlerta()) {
                case "Y" -> { tx.respuestaFm(d.folio()); tx.alertaFm(true); }
                case "N" -> tx.respuestaFm(d.folio());
                default  -> { }                                // otro valor: no se marca respuesta
            }
        }
        if (d.tcOrigen() == props.tcOrigenRevocaFm() || tx.tieneRespuestaFm()) {
            respuesta.aplica(tx);
            timeouts.olvida(tx.folioFm());
        }
    }
}

