gateway:
  ventanas-restringidas:
    - nombre: teleton-2014
      contrato: "9014946817"                 # String: conserva ceros
      desde: 2014-12-04T00:00:00
      hasta: 2014-12-07T03:00:00              # extremos exclusivos, como en el fuente
      permitidos:
        - { sistema-origen: "0015", solo-aplicacion: true }
        - { sistema-origen: "0501", solo-aplicacion: true }
        - { sistema-origen: "0618", clave: 1192 }
      rechazo-terminal: 483
      rechazo-otro: 482

// ---------------------------------------------------------------------------
public void validaVentanas(Transaccion tx) {
    if (!banderas.teletonActiva()) return;                 // HI 1011
    for (var v : props.ventanasRestringidas()) {
        LocalDateTime ts = tx.fechaHoraMovimiento();        // FEC-MAQUINA * 1000000 + HORA-MOVTO
        if (!v.contrato().equals(tx.numContrato())
                || !ts.isAfter(v.desde()) || !ts.isBefore(v.hasta())) continue;
        if (v.permitidos().stream().noneMatch(p -> p.aplica(tx))) {
            tx.rechaza(tx.vinoDeTerminal() ? v.rechazoTerminal() : v.rechazoOtro());
        }
    }
}

/**
 * En el fuente toda la lógica de stand-in está comentada y solo sobrevive el rechazo:
 * un contrato con MIGR-S111 = 1 o 4 no recibe ningún movimiento.
 */
public void validaMigracion(Transaccion tx) {
    int migr = tx.contrato().migracionS111();
    if (migr == 1 || migr == 4) {
        tx.rechaza(847);       // CTO. EN PROCESO DE MIGRACION NO RECIBE MOVIMIENTOS
        return;
    }
    if (tx.transaccionStandIn() && tx.baseAuxiliar()) {
        tx.rechaza(847);
    }
}

