@Service
@RequiredArgsConstructor
public class Cargos {

    private final GatewayProperties props;
    private final ClavesTransaccion claves;   // WS-CVE-NCHQSAB-PROTEG-IMP / -LIBERA-IMP

    /** 51020000-PROCESA-CARGOS. */
    @Transactional
    public void procesa(Transaccion tx) {
        if (tx.compensacionObanco())                                  sinAfectarSaldoB21(tx);
        else if (props.cargos().clavesSinAfectarSaldo().contains(tx.clave())) sinAfectarSaldo(tx);
        else if (tx.clave() == claves.protegeImporte())              reservaImporte(tx);
        else if (tx.clave() == claves.liberaImporte())               liberaImporte(tx);
        else                                                          cargo(tx);   // 00000000-CARGOS
    }
}
